// Solutions category nav: highlights the category (and customer) whose section has scrolled past a
// threshold line, and lists the active category's customers under its pill.
// Port of SolutionsCategoryNav.tsx; markup is generated by port-landing.mjs, which also emits the
// category/customer ids as JSON (the server render only includes the first category's customer links).

// How far below the navbar a section's top must cross before it counts as "reached"
const SCROLL_THRESHOLD_PX = 120;
const C = 'solutions-category-nav-';

// Matches the original exactly: --ifm-navbar-height is "3.75rem", so this parses to 3.75 rather than
// 60px, putting the threshold line ~124px from the top instead of the intended ~180px. Kept for parity.
function getNavbarHeight() {
  const parsed = Number.parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--ifm-navbar-height'));
  return Number.isNaN(parsed) ? 60 : parsed;
}

function isAtPageBottom() {
  return window.innerHeight + window.scrollY >= document.body.scrollHeight - 8;
}

// The last id, in document order, whose element has scrolled past the threshold line
function findReachedId(ids, threshold) {
  let reached;
  for (const id of ids) {
    const element = document.getElementById(id);
    if (element && element.getBoundingClientRect().top <= threshold) {
      reached = id;
    }
  }
  return reached;
}

export function initCategoryNav(root) {
  const nav = root.querySelector(`.${C}nav`);
  const categories = JSON.parse(root.querySelector('.solutions-nav-data')?.textContent ?? '[]');
  if (!nav || categories.length === 0) {
    return undefined;
  }

  const categoryIds = categories.map((category) => category.id);
  const items = Array.from(nav.querySelectorAll(`.${C}item`));
  let activeCategoryId = categoryIds[0];
  let activeCustomerId = undefined;
  let ticking = false;

  function render(categoryId, customerId) {
    const categoryChanged = categoryId !== activeCategoryId;
    activeCategoryId = categoryId;
    activeCustomerId = customerId;

    items.forEach((item, i) => {
      const category = categories[i];
      const isActive = category.id === activeCategoryId;
      const pill = item.querySelector(`.${C}pill`);
      pill.classList.toggle(`${C}pill-active`, isActive);
      toggleAriaCurrent(pill, isActive);

      let subList = item.querySelector(`.${C}sub-list`);
      if (!isActive || category.customers.length === 0) {
        subList?.remove();
        return;
      }
      if (!subList) {
        subList = document.createElement('div');
        subList.className = `${C}sub-list`;
        for (const customer of category.customers) {
          const link = document.createElement('a');
          link.href = `#${customer.id}`;
          link.className = `${C}sub-pill`;
          link.textContent = customer.name;
          subList.appendChild(link);
        }
        item.appendChild(subList);
      }
      subList.querySelectorAll(`.${C}sub-pill`).forEach((link, j) => {
        const isActiveCustomer = category.customers[j].id === activeCustomerId;
        link.classList.toggle(`${C}sub-pill-active`, isActiveCustomer);
        toggleAriaCurrent(link, isActiveCustomer);
      });
    });

    // Mobile: the category bar scrolls horizontally, so keep the active pill in view (a no-op on desktop)
    if (categoryChanged) {
      scrollActivePillIntoView();
    }
  }

  function scrollActivePillIntoView() {
    nav.querySelector(`.${C}pill-active`)?.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' });
  }

  function computeActive() {
    ticking = false;
    const threshold = getNavbarHeight() + SCROLL_THRESHOLD_PX;
    const atBottom = isAtPageBottom();
    const categoryId = atBottom ? categoryIds.at(-1) : (findReachedId(categoryIds, threshold) ?? categoryIds[0]);
    const customerIds = categories.find((category) => category.id === categoryId)?.customers.map((customer) => customer.id) ?? [];
    render(categoryId, atBottom ? customerIds.at(-1) : findReachedId(customerIds, threshold));
  }

  function onScroll() {
    if (!ticking) {
      ticking = true;
      requestAnimationFrame(computeActive);
    }
  }

  computeActive();
  scrollActivePillIntoView();
  window.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', onScroll);
  return () => {
    window.removeEventListener('scroll', onScroll);
    window.removeEventListener('resize', onScroll);
  };
}

function toggleAriaCurrent(el, isCurrent) {
  if (isCurrent) {
    el.setAttribute('aria-current', 'true');
  } else {
    el.removeAttribute('aria-current');
  }
}
